INSERT INTO `project_roost_review_snapshots` (`project_id`, `reviewed_at`, `source`, `source_hash`, `frontend_score`, `backend_score`, `security_score`, `overall_score`, `notes`, `priority_fix`, `created_at`) VALUES (@project_id, '2026-05-11 11:08:27', 'game-apps-summary', 'b14d3626901980d2dce805c74d328ff1e3b5a948ad668e5ccd573f586597d1d5', 8.4, 8.1, 8, 8.2, 'Retested after hardening: JSON file saves and direct public PHP bypasses were removed, SQL player/game migrations and a migration runner were added, game persistence is repository-backed and owner-scoped, guest linking now validates guest JWTs, CORS/login envs fail fast, and the frontend now uses centralized Axios/auth handling. Remaining limits are modest test depth and the older in-memory engine service shape.', '', NOW()) ON DUPLICATE KEY UPDATE `reviewed_at` = VALUES(`reviewed_at`), `frontend_score` = VALUES(`frontend_score`), `backend_score` = VALUES(`backend_score`), `security_score` = VALUES(`security_score`), `overall_score` = VALUES(`overall_score`), `notes` = VALUES(`notes`), `priority_fix` = VALUES(`priority_fix`);
